CREATE OR REPLACE FUNCTION rc_history.assert_operational_id(p_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE s text;BEGIN
 IF p_id IS NULL THEN RETURN;END IF;
 SELECT state INTO s FROM rc_history.identities WHERE exercise_id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'UNKNOWN_IDENTITY_NOT_REGISTERED' USING ERRCODE='42501';END IF;IF s<>'ACTIVE_ID' THEN RAISE EXCEPTION 'HISTORICAL_ID_RESERVED' USING ERRCODE='42501';END IF;
 END$function$

CREATE OR REPLACE FUNCTION rc_history.guard_runtime()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 DECLARE d jsonb; id text; oldid text; s text;
 BEGIN
 d:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 IF TG_TABLE_NAME='authorization_role_assignments' AND d->>'scope_type'<>'EXERCISE' AND (TG_OP<>'UPDATE' OR to_jsonb(OLD)->>'scope_type'<>'EXERCISE') THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END IF;
 id:=coalesce(d->>'exercise_id',d->>'scope_id',d->>'consumed_exercise_id');
 IF id IS NULL AND TG_OP='UPDATE' AND TG_TABLE_NAME='authorization_role_assignments' THEN id:=to_jsonb(OLD)->>'scope_id';END IF;
 IF id IS NULL THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END IF;
 IF TG_OP='UPDATE' THEN oldid:=coalesce(to_jsonb(OLD)->>'exercise_id',to_jsonb(OLD)->>'scope_id',to_jsonb(OLD)->>'consumed_exercise_id');IF oldid IS NOT NULL AND oldid IS DISTINCT FROM id THEN
 IF TG_TABLE_NAME<>'authorization_role_assignments' THEN RAISE EXCEPTION 'IDENTITY_RENAME_FORBIDDEN' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM rc_history.identities WHERE exercise_id IN(oldid,id) ORDER BY exercise_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rc_history.identities WHERE exercise_id=oldid AND state<>'ACTIVE_ID') THEN RAISE EXCEPTION 'HISTORICAL_ID_RESERVED' USING ERRCODE='42501';END IF;
 END IF;END IF;
 IF NOT EXISTS(SELECT 1 FROM rc_history.identities WHERE exercise_id=id) THEN RAISE EXCEPTION 'UNKNOWN_IDENTITY_NOT_REGISTERED' USING ERRCODE='42501';END IF;
 SELECT state INTO STRICT s FROM rc_history.identities WHERE exercise_id=id FOR UPDATE;
 IF TG_OP='DELETE' THEN
   IF true THEN RAISE EXCEPTION 'ARCHIVE_DELETE_NOT_READY' USING ERRCODE='42501';END IF;
 ELSE IF s<>'ACTIVE_ID' THEN RAISE EXCEPTION 'HISTORICAL_ID_RESERVED' USING ERRCODE='42501';END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 END$function$

CREATE OR REPLACE FUNCTION public.trusted_admin_grant_exercise_bootstrap(p_user_id uuid, p_issued_by uuid, p_expires_at timestamp with time zone, p_purpose text DEFAULT 'FRESH_EXERCISE_BOOTSTRAP'::text)
 RETURNS public.exercise_bootstrap_authorizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_authorization public.exercise_bootstrap_authorizations%rowtype;
  v_now timestamptz := clock_timestamp();
  v_purpose text := btrim(coalesce(p_purpose, ''));
begin
  if p_user_id is null or p_issued_by is null then
    raise exception 'INVALID_USER_IDENTIFIER' using errcode = '22023';
  end if;
  if p_expires_at is null
    or p_expires_at <= v_now
    or p_expires_at > v_now + interval '15 minutes' then
    raise exception 'INVALID_BOOTSTRAP_EXPIRY' using errcode = '22023';
  end if;
  if length(v_purpose) not between 1 and 160 then
    raise exception 'INVALID_BOOTSTRAP_PURPOSE' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from auth.users as target_user
    join public.operator_profiles as target_profile
      on target_profile.user_id = target_user.id
    where target_user.id = p_user_id
      and not target_user.is_anonymous
      and (target_user.banned_until is null or target_user.banned_until <= v_now)
      and target_profile.status = 'ACTIVE'
  ) then
    raise exception 'TARGET_OPERATOR_NOT_ACTIVE' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from auth.users as issuer
    where issuer.id = p_issued_by
      and not issuer.is_anonymous
      and (issuer.banned_until is null or issuer.banned_until <= v_now)
  ) then
    raise exception 'INVALID_ISSUER' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('EXERCISE_BOOTSTRAP' || E'\n' || p_user_id::text, 0)
  );

  update public.exercise_bootstrap_authorizations
  set status = 'REVOKED',
      revoked_at = v_now,
      revoked_by = p_issued_by
  where user_id = p_user_id
    and status = 'ACTIVE'
    and expires_at <= v_now;

  select bootstrap.*
  into v_authorization
  from public.exercise_bootstrap_authorizations as bootstrap
  where bootstrap.user_id = p_user_id
    and bootstrap.status = 'ACTIVE'
  for update;

  if found then
    if v_authorization.expires_at is distinct from p_expires_at
      or v_authorization.purpose is distinct from v_purpose then
      raise exception 'ACTIVE_BOOTSTRAP_CONFLICT' using errcode = '23505';
    end if;
    return v_authorization;
  end if;

  insert into public.exercise_bootstrap_authorizations (
    user_id,
    status,
    purpose,
    issued_at,
    expires_at,
    issued_by
  ) values (
    p_user_id,
    'ACTIVE',
    v_purpose,
    v_now,
    p_expires_at,
    p_issued_by
  )
  returning * into v_authorization;

  return v_authorization;
end;
$function$
